// Must equal DISCLOSURE in pawse/voice.py so the server does not prepend a second greeting.
const DISCLOSURE = 'Guten Tag, hier ist Pawse, die KI-Assistenz im Auftrag der Katzenhalterin oder des Katzenhalters.';
const FIRST_LINE = {
  original: `${DISCLOSURE} Ich bin ein KI-Assistent und kein Mensch.`,
  text: {
    en: 'Hello, this is Pawse, the AI assistant calling on behalf of the cat owner. I am an AI assistant, not a person.',
    zh: '您好，我是 Pawse，受猫主人委托的 AI 助手。我是 AI 助手，不是真人。',
  },
};
const STEP_INDEX = { vet: 2, insurance: 3 };
const T = (en, zh) => ({ en, zh });

const num = (v, d) => (typeof v === 'number' && Number.isFinite(v) ? v : d);

async function fetchStory(base) {
  const res = await fetch(`${base}/api/v1/demo/mimi`);
  if (!res.ok) throw new Error(`demo story unavailable (${res.status})`);
  return res.json();
}

/** Plays Gradium German audio for one AI line. Resolves true if audio played, false to fall back. */
async function playGradium(base, text, voice, state) {
  if (typeof Audio === 'undefined' || typeof URL === 'undefined' || !URL.createObjectURL) return false;
  try {
    const res = await fetch(`${base}/api/v1/voice/speech`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ text, language: 'de', voice, share_with_gradium: true }),
    });
    if (!res.ok || state.ended) return false;
    const url = URL.createObjectURL(await res.blob());
    if (state.ended) return false;
    return await new Promise((resolve) => {
      const a = new Audio(url);
      state.audio = a;
      const done = (ok) => {
        state.audio = null;
        try { URL.revokeObjectURL(url); } catch { /* ignore */ }
        resolve(ok);
      };
      a.onended = () => done(true);
      a.onerror = () => done(false);
      const p = a.play();
      if (p && p.catch) p.catch(() => done(false));
    });
  } catch {
    return false;
  }
}

function buildVetResult(story, lang, context) {
  const c = story.costs || {};
  return {
    kind: 'appointment',
    time: story.calendar?.appointment || '16:30',
    place: context.clinic?.name || (lang === 'zh' ? '诊所（演示）' : 'Clinic (demo)'),
    estimate: num(c.treatment, 600),
    currency: c.currency || 'CHF',
    note:
      lang === 'zh'
        ? '模拟：这是演示脚本，没有真的打电话，也没有真的预约。上门另加约 150 瑞郎。'
        : 'Simulated: demo script, no real call was made and nothing was booked. A home visit would add about CHF 150.',
    simulated: true,
  };
}

function buildInsuranceResult(story, lang) {
  const c = story.costs || {};
  const deductible = num(c.remaining_deductible, 300);
  const rate = num(c.reimbursement_rate, 0.8);
  const estimate = num(c.treatment, 600);
  const reimbursed = num(c.reimbursed, Math.max(estimate - deductible, 0) * rate);
  const cur = c.currency || 'CHF';
  const zh = lang === 'zh';
  const clinic = num(c.clinic, 385);
  const home = num(c.home, 510);
  return {
    kind: 'coverage',
    covered: true,
    currency: cur,
    deductible,
    rate,
    estimate,
    reimbursed,
    outOfPocket: estimate - reimbursed,
    points: [
      { ok: true, text: zh ? '意外从第一天起就保' : 'Accident covered from day 1' },
      {
        ok: true,
        text: zh
          ? `先付前 ${deductible} 瑞郎，之后报销 ${Math.round(rate * 100)}%`
          : `You pay the first ${cur} ${deductible}, then ${Math.round(rate * 100)}% is reimbursed`,
      },
      { ok: false, text: zh ? '上门费不保' : 'Home visit not covered', ref: 'AVB 1.2' },
      { ok: false, text: zh ? '之后的理疗不保' : 'Physiotherapy not covered', ref: 'AVB 1.2' },
      {
        ok: true,
        text: zh
          ? `估算自付：诊所约 ${cur} ${clinic}，上门约 ${cur} ${home}（含出租车 / 上门费）`
          : `Estimated cost to you: clinic about ${cur} ${clinic} vs home visit about ${cur} ${home}`,
      },
    ],
    simulated: true,
  };
}

export function createLivePhoneCall({ target = 'vet', lang = 'zh', context = {}, speed = 1 } = {}) {
  const base = PHONE_AGENT_URL || '';
  const listeners = new Set();
  const timers = new Set();
  const state = { ended: false, audio: null };
  let started = false;

  const emit = (e) => {
    if (!state.ended) listeners.forEach((l) => l(e));
  };
  const wait = (ms) =>
    new Promise((resolve) => {
      const id = setTimeout(() => {
        timers.delete(id);
        resolve();
      }, ms / speed);
      timers.add(id);
    });

  // Gradium audio only with explicit consent from the page (context.gradiumConsent === true).
  const voice = context.voice === 'my_voice' ? 'my_voice' : 'standard';

  async function say(line, useGradium) {
    if (useGradium && context.gradiumConsent === true && (await playGradium(base, line.original, voice, state))) return;
    if (state.ended) return;
    await speak(line.original, 'de', { speed, pitch: line.who === 'callee' ? 0.8 : 1.15 });
  }

  async function run() {
    emit({ type: 'status', state: 'dialing' });
    let story;
    try {
      story = await fetchStory(base);
    } catch (err) {
      emit({ type: 'error', message: `Phone agent: ${err.message}` });
      finish();
      return;
    }
    await wait(1500);
    if (state.ended) return;
    emit({ type: 'status', state: 'connected' });

    const step = (story.steps || [])[STEP_INDEX[target] ?? 2] || { lines: [] };
    const lines = [
      { who: 'ai', original: FIRST_LINE.original, text: FIRST_LINE.text[lang] ?? FIRST_LINE.text.en, gradium: true },
      ...(step.lines || []).map((l) => ({
        who: /^pawse/i.test(l.speaker) ? 'ai' : 'callee',
        original: l.german,
        // The backend subtitles are English; the zh UI shows them as is rather than inventing a translation.
        text: l.subtitle,
      })),
    ];
    for (const line of lines) {
      await wait(450);
      if (state.ended) return;
      emit({ type: 'speaking', who: line.who });
      const ev = { type: 'line', who: line.who, original: line.original, text: line.text };
      if (line.who === 'callee') ev.simulated = true;
      emit(ev);
      await say(line, line.gradium);
      if (state.ended) return;
      emit({ type: 'speaking', who: 'none' });
    }
    await wait(500);
    if (state.ended) return;
    emit({ type: 'result', ...(target === 'insurance' ? buildInsuranceResult(story, lang) : buildVetResult(story, lang, context)) });
    finish();
  }

  function finish() {
    if (state.ended) return;
    emit({ type: 'status', state: 'ended' });
    state.ended = true;
    timers.forEach(clearTimeout);
    timers.clear();
    if (state.audio) {
      try { state.audio.pause(); } catch { /* ignore */ }
      state.audio = null;
    }
    stopSpeech();
  }

  return {
    on(cb) {
      listeners.add(cb);
      return () => listeners.delete(cb);
    },
    start() {
      if (started) return;
      started = true;
      run().catch((err) => {
        emit({ type: 'error', message: String(err && err.message ? err.message : err) });
        finish();
      });
    },
    hangup: finish,
  };
}
import { VOICE_AGENT, CLINIC_SEARCH, PHONE_AGENT, MOCK_SPEED } from '../config.js';
import { createMockVoiceAgent } from './mockVoiceAgent.js';
import { createLiveVoiceAgent } from './liveVoiceAgent.js';
import { mockSearchClinics } from './mockClinicSearch.js';
import { liveSearchClinics } from './liveClinicSearch.js';
import { createMockPhoneCall } from './mockPhoneAgent.js';
import { createLivePhoneCall } from './livePhoneAgent.js';

export const IS_LIVE_VOICE = VOICE_AGENT === 'live';
export const IS_LIVE_CLINICS = CLINIC_SEARCH === 'live';
export const IS_LIVE_PHONE = PHONE_AGENT === 'live';
export const IS_MOCK = !IS_LIVE_VOICE || !IS_LIVE_CLINICS || !IS_LIVE_PHONE;

/** The page opens the microphone only if the active voice agent wants audio. */
export const VOICE_WANTS_AUDIO = IS_LIVE_VOICE;

/** 1. Voice conversation with Pawse. */
export function createVoiceAgent(opts) {
  return IS_LIVE_VOICE ? createLiveVoiceAgent(opts) : createMockVoiceAgent({ speed: MOCK_SPEED, ...opts });
}

/** 2. Nearby vet clinics. */
export function searchClinics(opts) {
  return IS_LIVE_CLINICS ? liveSearchClinics(opts) : mockSearchClinics({ speed: MOCK_SPEED, ...opts });
}

/** 3. Pawse calls the clinic or the insurer. */
export function createPhoneCall(opts) {
  return IS_LIVE_PHONE ? createLivePhoneCall(opts) : createMockPhoneCall({ speed: MOCK_SPEED, ...opts });
}
// Central switches. Set them in .env.local (see .env.example).
// import.meta.env is undefined outside Vite (e.g. plain-Node checks), so guard it.
const env = (typeof import.meta !== 'undefined' && import.meta.env) || {};

const param = (k) => {
  try {
    return new URLSearchParams(window.location.search).get(k);
  } catch {
    return null;
  }
};

/** 'mock' = scripted demo (default). 'live' = the Pawse backend. "?live=1" in the URL switches all three at runtime. */
const LIVE_ALL = param('live') === '1';
export const VOICE_AGENT = LIVE_ALL ? 'live' : env.VITE_VOICE_AGENT || 'mock';
export const CLINIC_SEARCH = LIVE_ALL ? 'live' : env.VITE_CLINIC_SEARCH || 'mock';
export const PHONE_AGENT = LIVE_ALL ? 'live' : env.VITE_PHONE_AGENT || 'mock';

export const VOICE_AGENT_URL = env.VITE_VOICE_AGENT_URL || '';
export const CLINIC_SEARCH_URL = env.VITE_CLINIC_SEARCH_URL || '';
export const PHONE_AGENT_URL = env.VITE_PHONE_AGENT_URL || '';

/** Mock playback speed. "?speed=3" in the URL plays the demo 3x faster (handy for rehearsing). */
export const MOCK_SPEED = (() => {
  const v = Number(param('speed'));
  return v > 0 ? v : 1;
})();
import { useEffect, useState } from 'react';

/**
 * Opens the camera and/or microphone while `enabled`.
 * Returns { stream, error } – error is set when the device can't be opened
 * (no device, permission denied, or plain http on a phone).
 */
export default function useUserMedia({ enabled = true, video = false, audio = false, facing = 'environment' } = {}) {
  const [stream, setStream] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!enabled || (!video && !audio)) {
      setStream(null);
      setError(null);
      return undefined;
    }
    const md = typeof navigator !== 'undefined' ? navigator.mediaDevices : null;
    if (!md || !md.getUserMedia) {
      setError('unsupported');
      return undefined;
    }

    let cancelled = false;
    let current = null;
    setError(null);
    md.getUserMedia({ video: video ? { facingMode: { ideal: facing } } : false, audio })
      .then((s) => {
        if (cancelled) {
          s.getTracks().forEach((tr) => tr.stop());
          return;
        }
        current = s;
        setStream(s);
      })
      .catch((e) => {
        if (!cancelled) setError(e && e.name ? e.name : 'error');
      });

    return () => {
      cancelled = true;
      if (current) current.getTracks().forEach((tr) => tr.stop());
      setStream(null);
    };
  }, [enabled, video, audio, facing]);

  return { stream, error };
}

