import { useState } from 'react';
import Avatar from '../components/Avatar.jsx';
import PlanPanel from '../components/PlanPanel.jsx';
import { buildSummary } from '../utils/summary.js';
import { copyText } from '../utils/copy.js';

export default function Plan({ t, lang, triage, vet, insurance, onCall, onRestart }) {
  const [copied, setCopied] = useState(false);
  const summary = buildSummary({ lang, triage, vet, insurance });

  return (
    <main className="plan">
      <header className="plan-head">
        <Avatar size={56} />
        <h1>{t.planTitle}</h1>
      </header>

      <div className="card">
        <PlanPanel t={t} triage={triage} vet={vet} insurance={insurance} onCall={onCall} />
      </div>

      <section className="card">
        <div className="card-head">
          <h2>{t.summary}</h2>
          <button
            type="button"
            className="btn soft small"
            onClick={async () => {
              if (await copyText(summary)) {
                setCopied(true);
                setTimeout(() => setCopied(false), 1800);
              }
            }}
          >
            {copied ? `✓ ${t.copied}` : t.copy}
          </button>
        </div>
        <pre className="summary">{summary}</pre>
      </section>

      <section className="card">
        <h2>{t.checklistTitle}</h2>
        <ul className="cov">
          {t.checklist.map((c, i) => (
            <li key={i} className="ok">
              <span className="cov-icon" aria-hidden="true">✓</span>
              <span>{c}</span>
            </li>
          ))}
        </ul>
      </section>

      <p className="disclaimer">{t.disclaimer}</p>
      <button type="button" className="btn ghost wide" onClick={onRestart}>
        {t.restart}
      </button>
    </main>
  );
}
// Plain-text case summary (copy-paste ready), built from whatever has happened so far.

const LABELS = {
  zh: {
    plan: '安排',
    estimate: '预估费用',
    insurance: '保险',
    back: '预计报销',
    pay: '预计自付',
    notCovered: '不保',
  },
  en: {
    plan: 'Plan',
    estimate: 'Estimate',
    insurance: 'Insurance',
    back: 'expected back',
    pay: 'you pay about',
    notCovered: 'not covered',
  },
};

export function buildSummary({ lang = 'zh', triage, vet, insurance }) {
  const L = LABELS[lang] || LABELS.en;
  const lines = [];
  if (triage && triage.summary) lines.push(triage.summary);
  if (vet) {
    lines.push(`${L.plan}: ${vet.time} · ${vet.place}`);
    lines.push(`${L.estimate}: ≈ ${vet.currency || 'CHF'} ${vet.estimate}`);
  }
  if (insurance) {
    const cur = insurance.currency || 'CHF';
    lines.push(
      `${L.insurance}: ${L.back} ≈ ${cur} ${insurance.reimbursed} · ${L.pay} ≈ ${cur} ${insurance.outOfPocket}`
    );
    const no = (insurance.points || []).filter((p) => !p.ok);
    if (no.length) {
      lines.push(`${L.notCovered}: ${no.map((p) => (p.ref ? `${p.text} (${p.ref})` : p.text)).join('; ')}`);
    }
  }
  return lines.join('\n');
}
